/** Fixed public educational media, byte-identical to the reviewed Hosting asset.
 * No path reads, tenant data, credentials, redirects or executable user input. */
import {createHash} from 'node:crypto';
const VIDEO_BASE64 = '';
export const PUBLIC_VIDEO_PATH='/arquivos/wmgj/guia-pre-cadastro-medico.mp4';
const EXPECTED_HASH='508b4013b0f092c35dd38b92024c9e9de130d0e6d87b402bea28951d8a749c31';
const video=Buffer.from(VIDEO_BASE64,'base64');
if(video.length!==64299||createHash('sha256').update(video).digest('hex')!==EXPECTED_HASH)throw Error('PUBLIC_VIDEO_INTEGRITY_FAILED');
const etag='"'+EXPECTED_HASH+'"';
export function publicVideoResponse(method:string,pathname:string,range?:string,ifRange?:string){
  if(pathname!==PUBLIC_VIDEO_PATH)return null;
  const headers:Record<string,string>={'Content-Type':'video/mp4','Content-Disposition':'attachment; filename="guia-pre-cadastro-medico.mp4"',
    'X-Content-Type-Options':'nosniff','Cache-Control':'no-store','Accept-Ranges':'bytes','ETag':etag};
  if(method!=='GET'&&method!=='HEAD')return {status:405,headers:{...headers,Allow:'GET, HEAD'},body:Buffer.alloc(0)};
  let start=0,end=video.length-1,status=200;
  // Range applies to GET; an If-Range mismatch returns the complete representation.
  if(method==='GET'&&range!==undefined&&(ifRange===undefined||ifRange===etag)){
    const match=/^bytes=(\d*)-(\d*)$/.exec(range);
    const rejected=()=>({status:416,headers:{...headers,'Content-Range':`bytes */${video.length}`,'Content-Length':'0'},body:Buffer.alloc(0)});
    if(!match||(!match[1]&&!match[2]))return rejected();
    if(!match[1]){
      const suffix=Number(match[2]);if(!Number.isSafeInteger(suffix)||suffix<=0)return rejected();
      start=Math.max(0,video.length-suffix);
    }else{
      start=Number(match[1]);end=match[2]?Number(match[2]):end;
      if(!Number.isSafeInteger(start)||!Number.isSafeInteger(end)||start>=video.length||end<start)return rejected();
      end=Math.min(end,video.length-1);
    }
    status=206;headers['Content-Range']=`bytes ${start}-${end}/${video.length}`;
  }
  headers['Content-Length']=String(end-start+1);
  return {status,headers,body:method==='HEAD'?Buffer.alloc(0):video.subarray(start,end+1)};
}
